<script lang="ts">
 import SoulTile from '../digital/SoulTile.svelte';
 import type {Soul} from '$lib/tabletop/rearrangement';
 let {tiles,canPlay=false,committed=[],selected=[],onDrop,onReorder,onSelect}:{tiles:Soul[];canPlay?:boolean;committed?:string[];selected?:string[];onDrop?:(tile:Soul,x:number,y:number)=>boolean;onReorder?:(ids:string[])=>void;onSelect?:(id:string)=>void}=$props();
 let rack:HTMLDivElement;let drag=$state<{tile:Soul;x:number;y:number;startX:number;startY:number;moving:boolean;pointer:number}|null>(null);
 function down(e:PointerEvent,tile:Soul){if(e.button!==0)return;e.preventDefault();(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);drag={tile,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moving:false,pointer:e.pointerId};}
 function move(e:PointerEvent){if(!drag||e.pointerId!==drag.pointer)return;drag.x=e.clientX;drag.y=e.clientY;drag.moving ||=Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5;}
 function up(e:PointerEvent){if(!drag)return;const d=drag;drag=null;if(!d.moving){onSelect?.(d.tile.id);return;}const box=rack.getBoundingClientRect();if(e.clientY>=box.top-20&&e.clientY<=box.bottom+20){const others=[...rack.querySelectorAll<HTMLElement>('[data-rack-tile]')].filter(el=>el.dataset.rackTile!==d.tile.id);const at=others.findIndex(el=>{const b=el.getBoundingClientRect();return e.clientY<b.top+b.height&&e.clientX<b.left+b.width/2;});const ids=tiles.map(t=>t.id).filter(id=>id!==d.tile.id);ids.splice(at<0?ids.length:at,0,d.tile.id);onReorder?.(ids);}else if(canPlay)onDrop?.(d.tile,e.clientX,e.clientY);}
</script>
<div class="rack" bind:this={rack} aria-label="Your rack. Drag souls to reorder or play into Heaven.">
 {#each tiles as tile (tile.id)}<button data-rack-tile={tile.id} class:selected={selected.includes(tile.id)} class:committed={committed.includes(tile.id)} class:lifted={drag?.tile.id===tile.id&&drag.moving} aria-label={`${tile.color} ${tile.rank}${committed.includes(tile.id)?', Scales commitment':''}`} aria-pressed={selected.includes(tile.id)} onpointerdown={e=>down(e,tile)} onpointermove={move} onpointerup={up} onpointercancel={()=>drag=null} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect?.(tile.id);}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const ids=tiles.map(t=>t.id),i=ids.indexOf(tile.id),j=Math.max(0,Math.min(ids.length-1,i+(e.key==='ArrowLeft'?-1:1)));[ids[i],ids[j]]=[ids[j],ids[i]];onReorder?.(ids);}}}><SoulTile rank={tile.rank} color={tile.color} size={44}/>{#if committed.includes(tile.id)}<span class="scale-dot" title="Scales commitment">◆</span>{/if}</button>{/each}
</div>
{#if drag?.moving}<div class="rack-ghost" style={`left:${drag.x-22}px;top:${drag.y-32}px`}><SoulTile rank={drag.tile.rank} color={drag.tile.color} size={44}/></div>{/if}
<style>
 .rack{display:flex;flex-wrap:wrap;align-items:flex-start;gap:4px;padding:12px 14px 16px;min-height:94px;background:linear-gradient(#76542d,#a6814c 9%,#5d3e24 88%,#c6a76c 92%,#47301e);border:1px solid #c3a366;border-radius:9px;box-shadow:0 5px 12px #231b2222,inset 0 0 12px #291c16}.rack button{position:relative;background:transparent;border:0;padding:0;min-height:0;line-height:0;touch-action:none;cursor:grab;flex:none;border-radius:6px}.rack button.selected{outline:2px solid #ffe093;transform:translateY(-6px)}.rack button.committed{margin-left:8px;border-bottom:3px solid #ffe7a1}.rack button.lifted{opacity:.3}.rack button:focus-visible{outline:3px solid #fff1ae}.scale-dot{position:absolute;bottom:-7px;left:40%;font:10px Georgia;color:#fff0b8}.rack-ghost{position:fixed;pointer-events:none;z-index:1000;filter:drop-shadow(0 8px 5px #0006)}
</style>
